function contactEmailFromLinks(links=[]){const contact=links.find(link=>link.label==='Gmail'&&safeUrl(link.url));if(!contact)return '';try{const url=new URL(contact.url);return url.origin==='https://mail.google.com'?url.searchParams.get('to')||'':''}catch{return ''}}
function setupExtendedProfileFields(){const extra=Object.keys(PLATFORMS).filter(key=>!$(key));const customField=$('customLinks').parentElement,extraWrap=document.createElement('div');extraWrap.className='field full';extraWrap.innerHTML='<label>More platforms</label><div class="extra-platform-grid"></div>';for(const key of extra){const field=document.createElement('div');field.className='field';const label=document.createElement('label');label.htmlFor=key;label.textContent=PLATFORMS[key];const input=document.createElement('input');input.id=key;input.type='url';input.placeholder='https://';input.setAttribute('aria-label',`${PLATFORMS[key]} profile URL`);field.append(label,input);extraWrap.querySelector('.extra-platform-grid').append(field);const option=document.createElement('option');option.value=key;option.textContent=PLATFORMS[key];$('platformFilter').insertBefore(option,$('platformFilter').lastElementChild)}customField.parentElement.insertBefore(extraWrap,customField);const emailField=document.createElement('div');emailField.className='field full';emailField.innerHTML='<label for="publicEmail">Public contact email (optional)</label><input id="publicEmail" type="email" maxlength="254" autocomplete="email" placeholder="you@example.com"><span class="hint">This is shown publicly on the creator page as a Gmail compose link. Do not enter your sign-in email unless you want it public.</span>';const publishedField=$('publishedUrl').parentElement;publishedField.parentElement.insertBefore(emailField,publishedField)}
function notify(message,error=false){const el=$('toast');el.textContent=message;el.classList.toggle('error',error);el.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('show'),5000)}
function requestResult(request){return new Promise((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||Error('Database request failed.'))})}
function transactionDone(tx){return new Promise((resolve,reject)=>{tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||Error('Database operation failed.'));tx.onabort=()=>reject(tx.error||Error('Database operation was cancelled.'))})}
