async function all(store){const tx=db.transaction(store,'readonly'),result=await requestResult(tx.objectStore(store).getAll());await transactionDone(tx);return result}
async function save(store,record){const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(record);await transactionDone(tx)}
async function saveMany(stores,recordsByStore){const tx=db.transaction(stores,'readwrite');for(const store of stores){const os=tx.objectStore(store);os.clear();(recordsByStore[store]||[]).forEach(record=>os.put(record))}await transactionDone(tx)}
function dataUrlToBlob(value){if(typeof value!=='string'||!/^data:image\/(png|jpeg|webp|gif);base64,/i.test(value))throw Error('Backup contains an invalid image.');const [meta,data]=value.split(',');if(!data||data.length>1700000)throw Error('Backup image is invalid or too large.');const mime=meta.slice(5,meta.indexOf(';')),raw=atob(data),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);if(bytes.length>1200000)throw Error('Imported images must be smaller than 1.2 MB.');return new Blob([bytes],{type:mime})}
function blobToDataUrl(blob){if(!blob)return Promise.resolve('');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error||Error('Could not read image for backup.'));reader.readAsDataURL(blob)})}
function imageUrl(blob){if(!blob)return '';const url=URL.createObjectURL(blob);objectUrls.push(url);return url}
function releaseUrls(){objectUrls.forEach(url=>URL.revokeObjectURL(url));objectUrls=[]}
function clearEditorImagePreviews(){Object.values(editorImageUrls).forEach(url=>URL.revokeObjectURL(url));editorImageUrls={}}
function showEditorImage(inputId,imageId,removeId,blob){const input=$(inputId),image=$(imageId),remove=$(removeId);if(editorImageUrls[imageId])URL.revokeObjectURL(editorImageUrls[imageId]);const selected=input.files[0],source=selected||blob;image.hidden=!source;remove.hidden=!source;if(source){const url=URL.createObjectURL(source);editorImageUrls[imageId]=url;image.src=url}else image.removeAttribute('src')}
function setTheme(theme){if(!THEMES[theme])theme='normal';document.body.dataset.theme=theme;$('appTheme').value=theme;try{localStorage.setItem(THEME_KEY,theme)}catch(error){notify(`Theme changed but could not be saved: ${error.message}`,true)}}
function themeCSS(theme){if(theme==='normal'&&window.matchMedia('(prefers-color-scheme: light)').matches)return{...THEMES.normal,accent:'#7660b8',background:'#f7f7fb',text:'#20212a'};return THEMES[theme]||THEMES.normal}
function usesThemeDefaultBackground(background){const color=String(background||'').toLowerCase();return !color||Object.values(THEMES).some(theme=>theme.background.toLowerCase()===color)||['#f7f7fb'].includes(color)}
function customLinkRows(links=[]){const parent=$('customLinks');parent.replaceChildren();links.forEach(link=>addCustomLink(link))}
function addCustomLink(link={label:'',url:''}){const row=document.createElement('div');row.className='custom-link-row';const label=document.createElement('input');label.className='custom-label';label.maxLength=40;label.placeholder='Link label';label.value=link.label||'';label.setAttribute('aria-label','Custom link label');const url=document.createElement('input');url.className='custom-url';url.type='url';url.placeholder='https://example.com';url.value=link.url||'';url.setAttribute('aria-label','Custom link URL');const up=document.createElement('button');up.type='button';up.textContent='↑';up.title='Move link up';up.setAttribute('aria-label','Move link up');up.addEventListener('click',()=>{const prev=row.previousElementSibling;if(prev)row.parentElement.insertBefore(row,prev)});const down=document.createElement('button');down.type='button';down.textContent='↓';down.title='Move link down';down.setAttribute('aria-label','Move link down');down.addEventListener('click',()=>{const next=row.nextElementSibling;if(next)row.parentElement.insertBefore(next,row)});const remove=document.createElement('button');remove.type='button';remove.textContent='Remove';remove.className='secondary';remove.addEventListener('click',()=>row.remove());row.append(label,url,up,down,remove);$('customLinks').append(row)}
function getCustomLinks(){return [...$('customLinks').querySelectorAll('.custom-link-row')].map(row=>({label:row.querySelector('.custom-label').value.trim(),url:row.querySelector('.custom-url').value.trim()})).filter(x=>x.label||x.url).map(x=>{if(!x.label||!safeUrl(x.url))throw Error('Every custom link needs a label and a valid http or https URL.');return{label:x.label,url:safeUrl(x.url)}})}
function linkDetail(value){try{const url=new URL(value),path=url.pathname.split('/').filter(Boolean).join('/');return path||url.hostname.replace(/^www\./,'')}catch{return value}}
function socialLink(label,url,icon='↗',detail=linkDetail(url),href=safeUrl(url),platform=''){const external=href.startsWith('http');return `<a class="social-link" ${platform?`data-platform="${escapeHtml(platform)}"`:''} href="${escapeHtml(href)}"${external?' target="_blank" rel="noopener noreferrer"':''} aria-label="${escapeHtml(`${label} ${detail}`)}"><span class="social-icon" aria-hidden="true">${escapeHtml(icon)}</span><span class="social-copy"><strong>${escapeHtml(label)}</strong><small>${escapeHtml(detail)}</small></span><span class="social-arrow" aria-hidden="true">↗</span></a>`}
function socialLinks(p){const links=Object.entries(PLATFORMS).filter(([key])=>safeUrl(p.socials?.[key])).map(([key,label])=>socialLink(label,p.socials[key],PLATFORM_ICONS[key],linkDetail(p.socials[key]),safeUrl(p.socials[key]),key));const contact=(p.customLinks||[]).find(link=>link.label==='Gmail'&&safeUrl(link.url));if(contact){const email=contactEmailFromLinks(p.customLinks);if(validEmail(email))links.push(socialLink('Email',`mailto:${email}`,'✉',email,`mailto:${email}`,'email'))}return links.join('')}
function customSocialLinks(links=[]){const email=contactEmailFromLinks(links);return links.filter(link=>safeUrl(link.url)&&!(link.label==='Gmail'&&validEmail(email))).map(link=>socialLink(link.label,link.url)).join('')}
function renderProfile(p,preview=false){const theme=themeCSS(p.theme),avatar=imageUrl(p.avatarBlob),cover=imageUrl(p.coverBlob),links=socialLinks(p),custom=customSocialLinks(p.customLinks);const gradient={sunrise:'linear-gradient(125deg,#f7c66b,#d88778)',ocean:'linear-gradient(125deg,#143a65,#4da7b8)',cosmic:'linear-gradient(125deg,#493e89,#aa78bd)'}[p.backgroundGradient]||'',background=usesThemeDefaultBackground(p.backgroundColor)?'':p.backgroundColor;const profileStyle=[`--profile-accent:${theme.accent}`,background?`--profile-bg:${escapeHtml(background)}`:'',gradient?`--profile-gradient:${gradient}`:''].filter(Boolean).join(';'),coverStyle=cover?`style="background-image:${p.theme==='evil'?'linear-gradient(125deg,#730c2699,#13080de0),':''}linear-gradient(#0002,#0003),url('${cover}')"`:'';return `<article class="profile-page theme-${escapeHtml(p.theme||'normal')}" style="${profileStyle}"><div class="profile-cover" ${coverStyle}></div><div class="profile-content">${avatar?`<img class="avatar" src="${avatar}" alt="${escapeHtml(p.name)} profile picture">`:'<div class="avatar avatar-empty" aria-hidden="true">✦</div>'}<span class="tag">${escapeHtml(p.category||'Other')}</span><span class="tag">${escapeHtml(theme.label)}</span><h2>${escapeHtml(p.name)}</h2><div class="handle">@${escapeHtml(p.slug)}</div><p class="bio">${escapeHtml(p.bio||'')}</p>${p.description?`<p class="description">${escapeHtml(p.description)}</p>`:''}<nav class="socials" aria-label="Social links">${links}${custom}</nav>${p.publishedUrl?`<p><a class="published" href="${escapeHtml(safeUrl(p.publishedUrl))}" target="_blank" rel="noopener noreferrer">Open recorded published page ↗</a></p>`:''}<p class="meta">Created ${escapeHtml(formatDate(p.createdAt))} · Modified ${escapeHtml(formatDate(p.updatedAt))}${p.exportedAt?` · Exported ${escapeHtml(formatDate(p.exportedAt))}`:''}</p>${preview?'<button type="button" class="secondary report-page">Report this page</button>':''}</div></article>`}
function formatDate(value){const date=new Date(value);return Number.isNaN(+date)?'unknown':date.toLocaleDateString()}
function card(p){const avatar=imageUrl(p.avatarBlob);return `<article class="creator-card theme-${escapeHtml(p.theme||'normal')}" style="--profile-accent:${themeCSS(p.theme).accent}"><div class="card-cover" ${p.coverBlob?`style="background-image:url('${imageUrl(p.coverBlob)}')"`:''}></div><div class="card-content">${avatar?`<img class="card-avatar" src="${avatar}" alt="">`:'<div class="card-avatar avatar-empty">✦</div>'}<h3>${escapeHtml(p.name)}</h3><div class="handle">@${escapeHtml(p.slug)}</div><span class="tag">${escapeHtml(p.category||'Other')}</span><span class="tag">${escapeHtml(themeCSS(p.theme).label)}</span><p class="bio">${escapeHtml(p.bio||'No biography added.')}</p><div class="socials">${socialLinks(p)||'<span class="muted">No social links yet</span>'}</div>${p.publishedUrl?'<span class="published-badge">External public URL saved · Profile data stays local</span>':'<span class="draft-badge">Local to this browser · Not public</span>'}<div class="card-actions"><button data-action="preview" data-id="${escapeHtml(p.id)}">Preview</button><button data-action="share" data-id="${escapeHtml(p.id)}">Share</button><button data-action="export" data-id="${escapeHtml(p.id)}">Export</button><button data-action="edit" data-id="${escapeHtml(p.id)}">Edit</button><button data-action="duplicate" data-id="${escapeHtml(p.id)}">Duplicate</button><button data-action="report" data-id="${escapeHtml(p.id)}">Report</button><button class="danger" data-action="delete" data-id="${escapeHtml(p.id)}">Delete</button></div></div></article>`}
function renderCreatorQuota(){const limit=BASE_CREATOR_LIMIT+demoPacks*CREATORS_PER_PACK,status=$('creatorQuotaStatus');if(!status)return;status.textContent=`${profiles.length} of ${limit} creator pages used · ${Math.max(0,limit-profiles.length)} slots available${demoPacks?' · '+demoPacks+' demo pack(s) unlocked on this browser':''}`;$('demoUnlockCreatorPack').textContent=`Demo only: simulate $25 pack for 5 more (${demoPacks} unlocked)`}
function showCreatorQuota(){renderCreatorQuota();$('settings').scrollIntoView({behavior:'smooth',block:'center'});notify('Your creator page limit is reached. Review the demo-only pack option in Settings.',true)}
