function render(){releaseUrls();const q=$('search').value.trim().toLowerCase(),category=$('categoryFilter').value,platform=$('platformFilter').value,sort=$('sort').value;let list=profiles.filter(p=>(!category||p.category===category)&&(!platform||safeUrl(p.socials?.[platform]))&&`${p.name} ${p.slug} ${p.bio} ${p.description} ${p.category}`.toLowerCase().includes(q));list.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='created'?b.createdAt.localeCompare(a.createdAt):b.updatedAt.localeCompare(a.updatedAt));$('count').textContent=`${list.length} shown · ${profiles.length} saved locally`;$('grid').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><strong>No matching creator pages</strong><br>Create a profile or adjust search and filters.</div>';renderReports();renderCreatorQuota()}
function normalizeLegacy(data){if(!data||typeof data.id!=='string'||typeof data.name!=='string'||typeof data.slug!=='string')throw Error('Legacy profile data is incomplete; migration stopped without removing it.');return{...data,theme:'normal',category:'Other',description:'',backgroundColor:'#0b1020',backgroundGradient:'',socials:data.socials&&typeof data.socials==='object'?data.socials:{},customLinks:[],publishedUrl:'',avatarBlob:data.avatarData?dataUrlToBlob(data.avatarData):null,coverBlob:data.bannerData?dataUrlToBlob(data.bannerData):null,createdAt:data.createdAt||data.updatedAt||new Date().toISOString(),updatedAt:data.updatedAt||new Date().toISOString()}}
async function migrate(){const done=await requestResult(db.transaction('meta','readonly').objectStore('meta').get('migration-v1'));if(done)return;const raw=localStorage.getItem(LEGACY_KEY);if(raw){let data;try{data=JSON.parse(raw)}catch{throw Error('Older saved profiles could not be read. They were left untouched.')}if(!Array.isArray(data))throw Error('Older saved data has an unexpected format and was left untouched.');const migrated=data.map(normalizeLegacy);const existing=await all('profiles'),ids=new Set(existing.map(p=>p.id));const tx=db.transaction(['profiles','meta'],'readwrite');migrated.filter(p=>!ids.has(p.id)).forEach(p=>tx.objectStore('profiles').put(p));tx.objectStore('meta').put({key:'migration-v1',done:true});await transactionDone(tx);localStorage.removeItem(LEGACY_KEY)}else{await save('meta',{key:'migration-v1',done:true})}}
async function refresh(){profiles=await all('profiles');reports=await all('reports');render();await storageInfo()}
async function storageInfo(){const output=$('storageInfo');try{if(navigator.storage?.estimate){const usage=await navigator.storage.estimate();const used=usage.usage||0,quota=usage.quota||0;output.textContent=`Browser storage used: ${(used/1048576).toFixed(2)} MB${quota?` of ${(quota/1048576).toFixed(0)} MB estimated available`:''}. Data remains local to this browser.`}else output.textContent='Storage estimates are unavailable in this browser. Profiles remain in local IndexedDB.'}catch(error){output.textContent=`Could not estimate storage: ${error.message}`}}
async function refreshBackupReminder(){const reminder=$('backupReminder');try{const backup=await requestResult(db.transaction('meta','readonly').objectStore('meta').get(BACKUP_META_KEY));const date=backup?.exportedAt?new Date(backup.exportedAt):null;if(!date||Number.isNaN(date.getTime())){reminder.textContent='Backup reminder: no backup recorded yet. Export one now; reminders repeat every 30 days.';return}const age=Date.now()-date.getTime();if(age>=BACKUP_REMINDER_MS){const days=Math.floor(age/86400000);reminder.textContent=`Backup reminder: your last backup was exported ${days} days ago. Export a new backup to protect your local data.`}else reminder.textContent=`Last backup exported ${date.toLocaleDateString()}. A reminder will appear after 30 days.`}catch(error){reminder.textContent=`Could not check the backup reminder: ${error.message}`}}
function openEditor(p){if(!hasCreatorSlot(p?.id)){showCreatorQuota();return}editingId=p?.id||null;removeAvatar=false;removeCover=false;clearEditorImagePreviews();$('editorForm').reset();$('editorTitle').textContent=p?'Edit creator page':'Create creator page';const profileTheme=p?.theme||'normal';$('profileTheme').value=profileTheme;$('profileTheme').dataset.previousTheme=profileTheme;$('category').value=p?.category||'Other';$('backgroundColor').value=usesThemeDefaultBackground(p?.backgroundColor)?themeCSS(profileTheme).background:p.backgroundColor;$('backgroundGradient').value=p?.backgroundGradient||'';for(const key of Object.keys(PLATFORMS))$(key).value=p?.socials?.[key]||'';$('name').value=p?.name||'';$('slug').value=p?.slug||'';$('slug').dataset.touched='';$('bio').value=p?.bio||'';$('description').value=p?.description||'';$('publishedUrl').value=p?.publishedUrl||'';$('publicEmail').value=contactEmailFromLinks(p?.customLinks);customLinkRows((p?.customLinks||[]).filter(link=>link.label!=='Gmail'));showEditorImage('avatarFile','avatarPreview','removeAvatar',p?.avatarBlob);showEditorImage('coverFile','coverPreview','removeCover',p?.coverBlob);$('editorDialog').classList.add('open');document.body.classList.add('modal-open');$('name').focus()}
function closeDialog(dialog){$(dialog).classList.remove('open');if(dialog==='editorDialog'){clearEditorImagePreviews();removeAvatar=false;removeCover=false}if(!document.querySelector('.backdrop.open'))document.body.classList.remove('modal-open')}
function formProfile(old){const name=$('name').value.trim(),slug=$('slug').value.trim().toLowerCase(),email=$('publicEmail').value.trim();if(!name||!slug)throw Error('Creator name and username are required.');if(profiles.some(p=>p.slug.toLowerCase()===slug&&p.id!==old?.id))throw Error('That username is already used in your local directory.');if(email&&!validEmail(email))throw Error('Enter a valid public contact email address.');const socials={};for(const key of Object.keys(PLATFORMS)){const value=$(key).value.trim();if(value){const url=safeUrl(value);if(!url)throw Error(`Enter a valid http or https URL for ${PLATFORMS[key]}.`);socials[key]=url}}const published=$('publishedUrl').value.trim();if(published&&!safeUrl(published))throw Error('Published URL must use http or https.');const customLinks=getCustomLinks();if(email)customLinks.push({label:'Gmail',url:`https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(email)}`});const theme=$('profileTheme').value,backgroundColor=$('backgroundColor').value;return{id:old?.id||id(),name,slug,category:$('category').value,theme,bio:$('bio').value.trim(),description:$('description').value.trim(),socials,customLinks,backgroundColor:usesThemeDefaultBackground(backgroundColor)?'':backgroundColor,backgroundGradient:$('backgroundGradient').value,publishedUrl:published?safeUrl(published):'',avatarBlob:old?.avatarBlob||null,coverBlob:old?.coverBlob||null,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),exportedAt:old?.exportedAt||''}}
async function imageFile(input){const file=input.files[0];if(!file)return null;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Use a PNG, JPEG, WebP, or GIF image.');if(file.size>1200000)throw Error('Each image must be smaller than 1.2 MB.');return file.slice(0,file.size,file.type)}
$('editorForm').addEventListener('submit',async event=>{event.preventDefault();try{const old=profiles.find(p=>p.id===editingId);if(!hasCreatorSlot(old?.id)){showCreatorQuota();return}const p=formProfile(old),avatar=await imageFile($('avatarFile')),cover=await imageFile($('coverFile'));p.avatarBlob=removeAvatar?null:avatar||old?.avatarBlob||null;p.coverBlob=removeCover?null:cover||old?.coverBlob||null;await save('profiles',p);clearEditorImagePreviews();closeDialog('editorDialog');await refresh();if(window.GOEDrive?.isConnected()){try{const backedUp=await window.GOEDrive.backupProfile(p);if(backedUp)notify(`${backedUp} image(s) backed up to your Google Drive.`)}catch(error){notify(`Profile saved on this device, but its Google Drive image backup failed: ${error.message}`,true)}}try{await showShareLink(p)}catch(error){notify(`Profile saved, but its share link could not be prepared: ${error.message}`,true)}}catch(error){notify(error.message||'Could not save profile.',true)}});
$('copyShareLink').addEventListener('click',async()=>{const input=$('shareLinkValue');try{if(await copyShareLink(input.value)){notify('Creator page link copied.');return}input.focus();input.select();notify('Automatic copy was blocked. The link is selected; copy it with Ctrl+C.',true)}catch(error){notify(`Could not copy the creator page link: ${error.message}`,true)}});
$('avatarFile').addEventListener('change',()=>showEditorImage('avatarFile','avatarPreview','removeAvatar',null));$('coverFile').addEventListener('change',()=>showEditorImage('coverFile','coverPreview','removeCover',null));
$('removeAvatar').addEventListener('click',()=>{removeAvatar=true;$('avatarFile').value='';showEditorImage('avatarFile','avatarPreview','removeAvatar',null)});$('removeCover').addEventListener('click',()=>{removeCover=true;$('coverFile').value='';showEditorImage('coverFile','coverPreview','removeCover',null)});
$('name').addEventListener('input',()=>{if(!$('slug').dataset.touched)$('slug').value=$('name').value.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,48)});$('slug').addEventListener('input',()=>{$('slug').dataset.touched='true'});$('addCustomLink').addEventListener('click',()=>addCustomLink());
