function exportHtml(p){return blobToDataUrl(p.avatarBlob).then(avatar=>blobToDataUrl(p.coverBlob).then(cover=>{const theme=themeCSS(p.theme),links=[...Object.entries(PLATFORMS).filter(([key])=>safeUrl(p.socials?.[key])).map(([key,label])=>({label,url:p.socials[key]})),...(p.customLinks||[])].filter(x=>safeUrl(x.url)).map(x=>`<a href="${escapeHtml(safeUrl(x.url))}" target="_blank" rel="noopener noreferrer">${escapeHtml(x.label)} ↗</a>`).join('');const gradient={sunrise:'linear-gradient(125deg,#f7c66b,#d88778)',ocean:'linear-gradient(125deg,#143a65,#4da7b8)',cosmic:'linear-gradient(125deg,#493e89,#aa78bd)'}[p.backgroundGradient]||`linear-gradient(125deg,${p.backgroundColor||theme.background},${theme.accent}77)`;return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(p.name)} — Creator Page</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:20px;background:${escapeHtml(p.backgroundColor||theme.background)};color:${theme.text};font:16px/1.5 system-ui,sans-serif}.card{width:min(720px,100%);border:1px solid #8886;border-radius:22px;overflow:hidden;background:#1119}.cover{height:190px;background:${gradient} center/cover}.cover img{width:100%;height:100%;object-fit:cover}.body{padding:22px}.avatar{width:92px;height:92px;object-fit:cover;border-radius:24px;border:5px solid ${escapeHtml(p.backgroundColor||theme.background)};margin-top:-56px;background:#333}.handle{color:${theme.accent}}.bio,.description{white-space:pre-wrap}.links{display:flex;gap:9px;flex-wrap:wrap;margin-top:20px}.links a{padding:9px 12px;border-radius:10px;background:${theme.accent};color:#101010;text-decoration:none;font-weight:700}.tag{opacity:.8;font-size:13px}.meta{opacity:.7;font-size:12px;margin-top:24px}</style></head><body><main class="card"><div class="cover">${cover?`<img src="${escapeHtml(cover)}" alt="Cover image">`:''}</div><div class="body">${avatar?`<img class="avatar" src="${escapeHtml(avatar)}" alt="Profile picture">`:''}<div class="tag">${escapeHtml(p.category)} · ${escapeHtml(theme.label)}</div><h1>${escapeHtml(p.name)}</h1><div class="handle">@${escapeHtml(p.slug)}</div><p class="bio">${escapeHtml(p.bio)}</p>${p.description?`<p class="description">${escapeHtml(p.description)}</p>`:''}<nav class="links">${links||'<span>No links added.</span>'}</nav><p class="meta">Static export · Updates do not sync with the original profile.</p></div></main></body></html>`}))}
