function bytesToBase64Url(bytes){let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function base64UrlToBytes(value){if(!/^[A-Za-z0-9_-]+$/.test(value))throw Error('The shared page link contains invalid data.');const binary=atob(value.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(binary,char=>char.charCodeAt(0))}
async function sharePayloadToken(p,includeImages=true){const profile={...p,avatarData:includeImages?await blobToDataUrl(p.avatarBlob):'',coverData:includeImages?await blobToDataUrl(p.coverBlob):''};delete profile.avatarBlob;delete profile.coverBlob;const text=JSON.stringify({version:1,profile}),canCompress=typeof CompressionStream==='function';let bytes,encoding='raw';if(canCompress){const stream=new Blob([text]).stream().pipeThrough(new CompressionStream('gzip'));bytes=new Uint8Array(await new Response(stream).arrayBuffer());encoding='gz'}else bytes=new TextEncoder().encode(text);return `${encoding}.${bytesToBase64Url(bytes)}`}
function shareBaseUrl(){if(location.protocol==='https:'||location.protocol==='http:'){const base=new URL(location.href);base.search='';base.hash='';return base.href}return SHARE_BASE_URL}
async function profileShareUrl(p){let token=await sharePayloadToken(p),url=`${shareBaseUrl()}#share=${token}`;if(url.length>MAX_SHARE_URL_LENGTH&&(p.avatarBlob||p.coverBlob)){if(!confirm('This profile’s images make the share link too large for many apps. Create a reliable link without the profile and cover images?'))throw Error('Share canceled. You can remove the images or publish the standalone HTML page instead.');token=await sharePayloadToken(p,false);url=`${shareBaseUrl()}#share=${token}`}if(url.length>MAX_SHARE_URL_LENGTH)throw Error('This profile is too large for a reliable share link. Shorten its text or publish the standalone HTML page, then share its public URL.');return url}
async function decodeSharePayload(token){const separator=token.indexOf('.');if(separator<1)throw Error('This shared page link is incomplete.');const encoding=token.slice(0,separator),bytes=base64UrlToBytes(token.slice(separator+1));let text;if(encoding==='gz'){if(typeof DecompressionStream!=='function')throw Error('This browser cannot open compressed share links. Open the link in a current browser.');const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));text=await new Response(stream).text()}else if(encoding==='raw')text=new TextDecoder().decode(bytes);else throw Error('This shared page link uses an unsupported format.');const payload=JSON.parse(text);if(payload?.version!==1||!payload.profile)throw Error('This shared page link has an unsupported profile format.');return validateProfile(payload.profile)}
function renderSharedPage(p){document.body.classList.add('shared-page-mode');document.body.dataset.theme=p.theme||'normal';document.title=`${p.name} — Creator Page`;let robots=document.querySelector('meta[name="robots"]');if(!robots){robots=document.createElement('meta');robots.name='robots';document.head.append(robots)}robots.content='noindex,nofollow';const page=document.createElement('main');page.className='shared-page-view';page.innerHTML=`<div class="shared-page-heading"><a class="brand" href="${escapeHtml(shareBaseUrl())}"><span class="mark" aria-hidden="true">✦</span><span>GOD OF EVERYTHING<small>CREATOR HUB</small></span></a><span>Shared creator page</span></div><p class="shared-page-notice">Unlisted shared page: anyone with this link can view it. It is not encrypted or password protected. Viewing is read-only and does not give access to edit the owner's local profile.</p><div class="shared-profile">${renderProfile(p)}</div>`;document.body.append(page)}
