function decorateExportTheme(html,p){const doc=new DOMParser().parseFromString(html,'text/html'),theme=p.theme||'normal';doc.body.dataset.theme=theme;doc.querySelector('.card')?.classList.add(`theme-${theme}`);if(theme==='evil'){const style=doc.querySelector('style');if(style)style.textContent+='.card.theme-evil{border-color:#7d2638;background:#120a0e;box-shadow:0 20px 55px #38081480,0 0 0 1px #ff536922}.card.theme-evil .cover{position:relative;display:grid;place-items:center;isolation:isolate;background:radial-gradient(ellipse at 50% 0%,#8d1731 0,#4b1020 40%,#1b0c12 100%)}.card.theme-evil .cover img{filter:brightness(.62) sepia(.16) hue-rotate(300deg) saturate(1.35)}.card.theme-evil .cover:before{content:\"\";position:absolute;z-index:1;top:calc(50% - 39px);left:50%;width:114px;height:70px;transform:translateX(-50%);background:linear-gradient(135deg,#ff9aa5,#e53654 42%,#79152b);clip-path:polygon(0 100%,12% 37%,25% 0,37% 59%,50% 100%,63% 59%,75% 0,88% 37%,100% 100%);filter:drop-shadow(0 0 12px #ff334f99)}.card.theme-evil .cover:after{content:\"♆\";position:relative;z-index:2;width:76px;height:76px;display:grid;place-items:center;border:1px solid #ff8b9a99;border-radius:50%;background:radial-gradient(circle at 34% 28%,#69172a,#200b12 75%);color:#ffe8ec;font:48px Georgia,serif;text-shadow:0 0 14px #ff526a;box-shadow:0 0 30px #ff244833,inset 0 0 18px #ff334f33}.card.theme-evil .body{background:#120a0e;color:#fff5f5}.card.theme-evil h1{background:linear-gradient(100deg,#fff3f4 4%,#ff8795 58%,#ff536f);background-clip:text;color:transparent}.card.theme-evil .handle{color:#ff586f}.card.theme-evil .links a.social-link{border:1px solid #682535;background:linear-gradient(110deg,#30121c,#201018);color:#fff1f3}.card.theme-evil .social-arrow{color:#ff586f}'}return `<!doctype html>${doc.documentElement.outerHTML}`}
$('grid').addEventListener('click',async event=>{const button=event.target.closest('button[data-action]');if(!button)return;const p=profiles.find(x=>x.id===button.dataset.id);if(!p)return;try{switch(button.dataset.action){case'preview':openPreview(p);break;case'share':await shareProfile(p);break;case'edit':openEditor(p);break;case'export':await exportProfile(p);break;case'report':openReport(p);break;case'duplicate':{if(!hasCreatorSlot()){showCreatorQuota();break}const copy={...p,id:id(),name:`${p.name} (copy)`,slug:uniqueSlug(`${p.slug}-copy`),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),exportedAt:''};await save('profiles',copy);await refresh();notify('Profile duplicated.');break}case'delete':if(confirm(`Delete ${p.name}'s local profile? This cannot be undone.`)){const tx=db.transaction('profiles','readwrite');tx.objectStore('profiles').delete(p.id);await transactionDone(tx);await refresh();notify('Profile deleted from this device.')}break}}catch(error){if(error.name!=='AbortError')notify(error.message||'Could not complete action.',true)}});
function uniqueSlug(base){let slug=base.slice(0,48),n=2;while(profiles.some(p=>p.slug.toLowerCase()===slug.toLowerCase())){const suffix=`-${n++}`;slug=`${base.slice(0,48-suffix.length)}${suffix}`}return slug}
$('editorPreview').addEventListener('click',()=>{try{const old=profiles.find(x=>x.id===editingId),p=formProfile(old);p.avatarBlob=removeAvatar?null:$('avatarFile').files[0]||old?.avatarBlob||null;p.coverBlob=removeCover?null:$('coverFile').files[0]||old?.coverBlob||null;openPreview(p)}catch(error){notify(error.message,true)}});
$('previewContent').addEventListener('click',event=>{if(event.target.closest('.report-page')){const p=profiles.find(x=>x.id===previewId);if(p)openReport(p)}});$('previewReport').addEventListener('click',()=>{const p=profiles.find(x=>x.id===previewId);if(p)openReport(p)});$('previewShare').addEventListener('click',async()=>{const p=profiles.find(x=>x.id===previewId);if(!p)return;try{await shareProfile(p)}catch(error){if(error.name!=='AbortError')notify(error.message||'Could not share creator page.',true)}});$('previewExport').addEventListener('click',()=>{const p=profiles.find(x=>x.id===previewId);if(p)exportProfile(p)});
$('reportForm').addEventListener('submit',async event=>{event.preventDefault();const reference=$('reportReference').value.trim();if(reference&&!safeUrl(reference)){notify('Reference URL must use http or https.',true);return}const p=profiles.find(x=>x.id===$('reportPageId').value),r={id:id(),profileId:$('reportPageId').value,profileName:p?.name||'Creator page',slug:p?.slug||'',category:$('reportCategory').value,details:$('reportDetails').value.trim(),reference:reference?safeUrl(reference):'',status:'pending',createdAt:new Date().toISOString()};try{await save('reports',r);reports.unshift(r);closeDialog('reportDialog');renderReports();notify('Report saved on this device only; it was not sent.')}catch(error){notify(error.message||'Could not save report.',true)}});
function renderReports(){$('statProfiles').textContent=String(profiles.length);$('statPublicLinks').textContent=String(profiles.filter(p=>safeUrl(p.publishedUrl)).length);const root=$('reportsList');if(!reports.length){root.innerHTML='<p class="muted">No local reports.</p>';return}root.innerHTML=reports.map(r=>`<article class="report-row"><div><strong>${escapeHtml(r.profileName||'Creator page')} (@${escapeHtml(r.slug||'unknown')})</strong><span class="tag">${escapeHtml(r.category)}</span><span class="status">${escapeHtml(r.status)}</span><p>${escapeHtml(r.details)}</p>${r.reference?`<a href="${escapeHtml(safeUrl(r.reference))}" target="_blank" rel="noopener noreferrer">Reference ↗</a>`:''}<p class="hint">${escapeHtml(new Date(r.createdAt).toLocaleString())} · Local allegation, not a finding.</p></div><div class="report-actions"><button data-status="under-review" data-id="${escapeHtml(r.id)}">Under review</button><button data-status="dismissed" data-id="${escapeHtml(r.id)}">Dismiss</button><button data-status="action-taken" data-id="${escapeHtml(r.id)}">Action taken</button><button data-email="${escapeHtml(r.id)}">Draft email</button><button class="danger" data-delete-report="${escapeHtml(r.id)}">Delete report</button></div></article>`).join('')}
$('reportsList').addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;const r=reports.find(x=>x.id===button.dataset.id||x.id===button.dataset.deleteReport);if(!r)return;try{if(button.dataset.deleteReport){if(!confirm('Delete this local report? This cannot be undone.'))return;const tx=db.transaction('reports','readwrite');tx.objectStore('reports').delete(r.id);await transactionDone(tx);reports=reports.filter(item=>item.id!==r.id);renderReports();notify('Local report deleted.')}else if(button.dataset.status){r.status=button.dataset.status;await save('reports',r);renderReports();notify(`Local note changed to ${r.status}.`)}else if(button.dataset.email){const subject=encodeURIComponent(`Creator Hub report: ${r.profileName}`),body=encodeURIComponent(`Page: ${r.profileName} (@${r.slug})\nCategory: ${r.category}\nExplanation: ${r.details}\nReference: ${r.reference||'None'}\nCreated: ${r.createdAt}\n\nThis draft was prepared locally. It has not been sent.`);location.href=`mailto:visvamgg@gmail.com?subject=${subject}&body=${body}`}}catch(error){notify(error.message||'Could not update report.',true)}});
